import type { HTMLArkProps } from '@ark-ui/react/factory';
import { ark } from '@ark-ui/react/factory';
import { clsx } from 'clsx';
import { forwardRef } from 'react';
import styles from './Kbd.module.css';

const Kbd = forwardRef<HTMLElement, HTMLArkProps<'kbd'>>(function Kbd(
  { className, ...props },
  ref,
) {
  return (
    <ark.kbd
      ref={ref}
      {...props}
      data-scope="kbd"
      data-part="root"
      data-slot="kbd-root"
      className={clsx(styles.root, className)}
    />
  );
});

const KbdGroup = forwardRef<HTMLElement, HTMLArkProps<'span'>>(function KbdGroup(
  { className, ...props },
  ref,
) {
  return (
    <ark.span
      ref={ref}
      {...props}
      role="group"
      data-scope="kbd"
      data-part="group"
      data-slot="kbd-group"
      className={clsx(styles.group, className)}
    />
  );
});

export { Kbd, KbdGroup };

@layer moduix.components {
  .root {
    box-sizing: border-box;
    display: inline-flex;
    flex: none;
    min-width: var(--moduix-kbd-height, var(--moduix-size-xs));
    max-width: 100%;
    min-height: var(--moduix-kbd-height, var(--moduix-size-xs));
    align-items: center;
    justify-content: center;
    border: var(--moduix-kbd-border-width, var(--moduix-border-width-sm)) solid
      var(--moduix-kbd-border-color, var(--moduix-color-border));
    border-radius: var(--moduix-kbd-radius, var(--moduix-radius-sm));
    padding-inline: var(--moduix-kbd-padding-x, var(--moduix-spacing-2));
    background-color: var(--moduix-kbd-bg, var(--moduix-color-muted));
    box-shadow: var(
      --moduix-kbd-shadow,
      inset 0 -1px 0 color-mix(in oklab, currentColor 12%, transparent)
    );
    color: var(--moduix-kbd-color, var(--moduix-color-foreground));
    font-family: var(--moduix-font-mono);
    font-size: var(--moduix-text-xs);
    font-weight: var(--moduix-weight-medium);
    line-height: var(--moduix-line-height-text-xs);
    font-variant-numeric: tabular-nums;
    text-align: center;
    vertical-align: middle;
    overflow-wrap: anywhere;
    user-select: none;
  }

  .group {
    display: inline-flex;
    max-width: 100%;
    align-items: center;
    flex-wrap: wrap;
    gap: var(--moduix-spacing-1);
    color: var(--moduix-color-muted-foreground);
    vertical-align: middle;
  }
}
